referenceSolutions.javascript:
function islandLedgersTotalReceipt(links) {
  const a=links; let out=[];
  const n=a.length,seen=Array(n).fill(false);for(let start=0;start<n;start++){if(seen[start])continue;const stack=[start];seen[start]=true;let count=0;while(stack.length){const u=stack.pop();count++;for(let v=0;v<n;v++)if(a[u][v]&&!seen[v]){seen[v]=true;stack.push(v);}}out.push(count);}
  return out.reduce((s,x)=>s+x,0);
}

